  ('resp_1794359743942_kooz', 'Muhammad Akbar Kurniawan', 'Siswa Kelas XI', 'Ikhwan', '2074', 2.46, '{"k1_1":2,"k1_2":2,"k1_3":2,"k1_4":2,"k1_5":3,"k2_1":3,"k2_2":2,"k2_3":2,"k2_4":3,"k2_5":2,"k3_1":2,"k3_2":2,"k3_3":2,"k3_4":3,"k3_5":2,"k4_1":3,"k4_2":3,"k4_3":3,"k4_4":2,"k4_5":3,"k5_1":3,"k5_2":2,"k5_3":3,"k5_4":3,"k5_5":3,"k6_1":3,"k6_2":2,"k6_3":2,"k6_4":3,"k6_5":3,"k7_1":3,"k7_2":2,"k7_3":3,"k7_4":1,"k7_5":2,"_duration_seconds":848}'::jsonb, 'SAEMOGA SEKOLAH INI MEMILIKI PEMIMPIN (SEMUA ASPEK PEMIMPIN) YANG DAPAT MENJADI SEBAIK BAIKNYA PEMIMPIN. YANG DAPAT TERBUKA, MENERIMA SEGALA ASPIRASI, TIDAK KERAS KEPALA, MELAKUKAN MUSYAWARAH SEBELUM MEMBUAT KEBIJAKAN, TIDAK MEMBUAT KEBIJAKAN YANG MERUGIKAN PIHAK YANG TIDAK SALAH, SERTA MENJADI SEBAIK BAIKNYA USWATUN KHAZANAH, DAN LANGSUNG TURUN KELAPANGAN BUKAN HANYA DARI SEKEDAR LAPORAN ORANG (SEMOGA PANITIA BENAR2 MENGIRIMKAN ASPIRASI SATU INI KARENA KAMI PARA SISWA SUDAH MUAK DENGAN KEADAAN SAAT INI) DAN SAYA SANGAT AMAT BERHARAP SEKOLAH IONI TIDAK MENJADI INDONESIA KECIL YANG DIMANA ORANG DENGAN BECKINGAN ITU LEBIH "MULIA" WALAU IA DARIPADA ORANG YANG TIDAK BERSALAH', '2026-11-11T01:15:43.942+00:00'),
