-- =========================================================================
-- 4. View Tambahan: Rekapan Agregat per Sesi Evaluasi (WIB)
-- =========================================================================
CREATE OR REPLACE VIEW public.v_survey_session_recap AS
SELECT 
    CASE 
        WHEN (created_at AT TIME ZONE 'Asia/Jakarta')::date = '2026-11-02' THEN 'Sesi 1: Senin, 02 Nov 2026'
        WHEN (created_at AT TIME ZONE 'Asia/Jakarta')::date = '2026-11-05' THEN 'Sesi 2: Kamis, 05 Nov 2026'
        WHEN (created_at AT TIME ZONE 'Asia/Jakarta')::date = '2026-11-14' THEN 'Sesi 4: Sabtu, 14 Nov 2026'
        ELSE 'Sesi 3: Rabu, 11 Nov 2026 (+ Susulan)'
    END AS nama_sesi,
    COUNT(*) AS total_responden,
    COUNT(DISTINCT LOWER(TRIM(nama))) AS santri_unik,
    ROUND(AVG(total_score), 2) AS rerata_ikv,
    COUNT(*) FILTER (WHERE jenis_kelamin = 'Ikhwan' OR jenis_kelamin IS NULL) AS jumlah_ikhwan,
    COUNT(*) FILTER (WHERE jenis_kelamin = 'Akhwat') AS jumlah_akhwat
FROM public.survey_responses
GROUP BY 1
ORDER BY 1;

